INSERT INTO questions (id, exam_version_id, exam, supported_exams, skill, type_id, type_name, title, prompt, explanation, prep_time_seconds, time_limit_seconds, points, difficulty, tags) VALUES
('ielts-gt-letter-001', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'writing', 'ielts-writing-task1-letter', 'Write a letter', 'A damaged delivery', 'You should spend about 20 minutes on this task.

You recently bought a washing machine from a large electrical store, and it was delivered to your home yesterday. When you unpacked it, you found that it was damaged.

Write a letter to the manager of the store. In your letter

- describe what you bought and when it was delivered
- explain what is wrong with the washing machine
- say what you would like the store to do

Write at least 150 words.

You do NOT need to write any addresses.

Begin your letter as follows:

Dear Sir or Madam,', 'Tone: formal, to someone you do not know. Open with the salutation given, state your purpose in the first paragraph, and close with "Yours faithfully" and your full name. Cover all three bullet points and develop each one with relevant detail; a missing bullet point limits Task Achievement. Make the purpose of the letter clear, organise it into paragraphs, and keep the tone consistent throughout. There is no single correct letter.', 0, 1200, 20, 'medium', ARRAY['Original practice', 'IELTS', 'Writing', 'Task 1', 'General Training', 'Formal']),
('ielts-gt-letter-002', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'writing', 'ielts-writing-task1-letter', 'Write a letter', 'A neglected park', 'You should spend about 20 minutes on this task.

There is a public park near your home, but in recent months it has fallen into poor condition.

Write a letter to the local council. In your letter

- describe the park and how local people use it
- explain what the problems are
- suggest what the council could do to improve it

Write at least 150 words.

You do NOT need to write any addresses.

Begin your letter as follows:

Dear Sir or Madam,', 'Tone: formal, to someone you do not know. Open with the salutation given, state your purpose in the first paragraph, and close with "Yours faithfully" and your full name. Cover all three bullet points and develop each one with relevant detail; a missing bullet point limits Task Achievement. Make the purpose of the letter clear, organise it into paragraphs, and keep the tone consistent throughout. There is no single correct letter.', 0, 1200, 20, 'medium', ARRAY['Original practice', 'IELTS', 'Writing', 'Task 1', 'General Training', 'Formal']),
('ielts-gt-letter-003', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'writing', 'ielts-writing-task1-letter', 'Write a letter', 'A weekend job at a museum', 'You should spend about 20 minutes on this task.

