-- Around Millbrook: Community Noticeboard (GT Section 1, 714 words)
INSERT INTO reading_passages (id, exam_version_id, title, subtitle, paragraphs, word_count, difficulty, topic, tags, passage_slot, modules) VALUES
('rp-gt1-millbrook', 'ielts-2026-01', 'Around Millbrook: Community Noticeboard', 'Six notices from a town noticeboard', '[{"label": "A", "text": "Millbrook Leisure Centre: pool timetable changes. From Monday 3 March, the main pool at Millbrook Leisure Centre will close at 8 p.m. on weekdays instead of 9.30 p.m., while essential repairs are carried out to the heating system. The learner pool is not affected and will keep its usual opening hours. Early-morning lane swimming, which starts at 6.30 a.m., will also continue as normal. Members who have booked lessons after 8 p.m. will be contacted by the centre and offered a place in a Saturday class at no extra charge. The work is expected to take about six weeks, and updates will be posted at reception and on the centre''s website."}, {"label": "B", "text": "For sale: family bicycles. Two adult bicycles and one child''s bicycle for sale, all in good working order. The adult bikes are three years old and have been serviced recently at a local cycle shop; the child''s bike is suitable for ages six to nine and comes with stabilisers, which can easily be removed. We are moving abroad and must sell quickly, so the price for all three together is £180. We would prefer not to sell them separately. Helmets are included free of charge. Please call Maria after 6 p.m. on weekdays, or at any time at weekends. Buyers must collect the bicycles from Elm Road. The bicycles can be viewed before you buy by arrangement."}, {"label": "C", "text": "Evening classes at Millbrook College. Millbrook College is running ten-week evening courses in Spanish, Italian and Mandarin, starting in the week of 14 April. Classes last two hours and are held once a week. Beginners are welcome in all three languages, and an intermediate group will also run in Spanish if at least eight people enrol. The fee is £95 per course, with a reduced rate of £60 for people over sixty-five and for full-time students. Course books are not included in the fee. Places can be booked online or in person at the college office, which is open until 7 p.m. from Monday to Thursday. Each class has a maximum of fifteen students, so that everyone has a chance to speak."}, {"label": "D", "text": "Found at Millbrook station. Items left on trains or at Millbrook station are kept at the lost property office next to the ticket hall for one month. After that, anything unclaimed is given to local charities, except for passports and bank cards, which are handed to the police. To collect an item, you will need to describe it and show some form of identification. There is no charge for collecting lost property in person, but items that have to be sent by post will be charged at cost. The office is open from 8 a.m. to 4 p.m., Monday to Friday; it is closed at weekends and on public holidays. Umbrellas, which make up the largest group of items handed in, are kept for only two weeks."}, {"label": "E", "text": "The farmers'' market is moving. Millbrook''s monthly farmers'' market, which has been held in the car park behind the town hall for the past twelve years, is moving to a new home. From May, the market will take place in Victoria Park, beside the bandstand, on the first Sunday of every month from 9 a.m. to 1 p.m. The move will make room for twenty more stalls, including several selling hot food. Parking will be available at the park''s north entrance, but visitors are encouraged to walk or cycle if they can. Stallholders who wish to apply for a place should contact the market office by the end of March. Dogs on leads are welcome, and a shuttle bus will run from the railway station on market days."}, {"label": "F", "text": "Volunteer drivers wanted. Millbrook Community Transport is looking for volunteer drivers to take older residents to hospital appointments. Volunteers use their own cars and are paid a mileage allowance to cover fuel costs. You will need to have held a full driving licence for at least three years, and you must be willing to give at least one morning or afternoon a fortnight. No previous experience of care work is needed, as all new drivers attend a half-day training session. For an application form, visit the Community Transport office on Station Road or telephone 01632 960 418. Journeys usually take place on weekdays between 9 a.m. and 5 p.m."}]'::jsonb, 714, 'easy', 'Community notices', ARRAY['IELTS Reading', 'General Training', 'GT Section 1', 'Original practice'], 'custom', ARRAY['general_training'])
ON CONFLICT (id) DO NOTHING;
