-- Westfield Adult Education: Autumn Short Courses (GT Section 1, 718 words)
INSERT INTO reading_passages (id, exam_version_id, title, subtitle, paragraphs, word_count, difficulty, topic, tags, passage_slot, modules) VALUES
('rp-gt1-westfield', 'ielts-2026-01', 'Westfield Adult Education: Autumn Short Courses', 'Six course descriptions from a college brochure', '[{"label": "A", "text": "First Aid for Parents. This one-day course covers the most common emergencies involving babies and young children, including choking, burns and high temperatures. It runs on Saturday 11 October from 10 a.m. to 4 p.m. and costs £40, which includes a light lunch. Everyone who completes the day receives a certificate, although this is not a professional qualification and cannot be used for work in childcare. Parents may not bring children to the session. Grandparents and other carers are also welcome to attend. The course is taught by a paramedic with many years of experience. Places are limited to twenty and usually fill quickly, so we recommend booking early."}, {"label": "B", "text": "Introduction to Bookkeeping. Aimed at people who run a small business or are planning to start one, this eight-week course explains how to keep simple accounts, record expenses and prepare for a tax return. Sessions take place on Tuesday evenings from 6.30 to 8.30 p.m. Participants should bring their own laptop, as the college computer room is not available in the evenings. No previous knowledge of accounting is needed. The fee is £120, and payment can be made in two instalments if you prefer. By the end of the course, you should be able to set up a simple spreadsheet to track the money coming into and going out of your business."}, {"label": "C", "text": "Photography with Your Phone. Learn to take better photographs using nothing more than the phone in your pocket. Over four Thursday afternoons, you will practise composition, lighting and simple editing. Two of the sessions are held outdoors in the town centre; if the weather is poor, these will be moved indoors and a different topic will be covered instead. The course is free for people who are currently unemployed, and costs £45 for everyone else. Please make sure your phone is fully charged before each session. You do not need an expensive phone, as the techniques work on most models from the last five years. At the end of the course, a selection of participants'' photographs will be displayed in the college library."}, {"label": "D", "text": "Cooking on a Budget. In six weekly sessions at the Riverside Community Centre kitchen, you will learn to plan meals, reduce food waste and cook healthy dishes for less than £2 a portion. All ingredients are provided and are included in the course fee of £75, and you will take home what you cook each week. Numbers are limited to ten people in each group because of the size of the kitchen, so early booking is advised. Please tell us about any food allergies when you enrol. Sessions are led by a professional chef who has worked in several local restaurants, and aprons are provided."}, {"label": "E", "text": "Job Interview Skills. Run in partnership with several local employers, this two-evening course helps you prepare for job interviews. On the first evening, managers from local firms explain what they look for in candidates. On the second, each participant takes part in a practice interview, which is filmed so that you can watch it back and receive feedback. The course is free, but places must be reserved in advance. It is particularly suitable for people who are returning to work after a long break. You will also receive advice on writing a covering letter and on answering difficult questions, such as why you left your last job. Please bring a copy of your current CV to the first session, even if it is not yet complete, as it will be used during the practice interview."}, {"label": "F", "text": "Beginners'' Yoga. This ten-week class introduces the basic positions and breathing techniques of yoga. It is suitable for all ages and fitness levels, and mats are provided, although you are welcome to bring your own. Wear loose, comfortable clothing and avoid eating a large meal in the two hours before a class. If you are pregnant or have a back injury, please bring a note from your doctor confirming that you can take part. The fee is £85 for the full course, and a free trial class is held in the first week. Classes are held on Monday evenings in the main hall, which has changing facilities and showers. The tutor has taught yoga at the college for over ten years and will suggest simple exercises that you can practise at home between classes."}]'::jsonb, 718, 'easy', 'Adult education', ARRAY['IELTS Reading', 'General Training', 'GT Section 1', 'Original practice'], 'custom', ARRAY['general_training'])
ON CONFLICT (id) DO NOTHING;
